## C++ benchmark

`tests/core/object/test_bench_object_alloc.cpp`, run with `godot --test bench-object-alloc`:

```cpp
#include "tests/test_macros.h"

TEST_FORCE_LINK(test_bench_object_alloc)

#include "core/io/resource.h"
#include "core/object/object.h"
#include "core/object/ref_counted.h"
#include "scene/main/node.h"

#include <chrono>
#include <cinttypes>
#include <cstdio>

static const int N = 1'000'000;
static const int REPS = 9;

static uintptr_t sink = 0;

template <typename F>
static void run_bench(const char *p_name, F p_fn) {
	p_fn(); // Warmup.
	double results[REPS];
	for (int rep = 0; rep < REPS; rep++) {
		auto t0 = std::chrono::steady_clock::now();
		p_fn();
		auto t1 = std::chrono::steady_clock::now();
		results[rep] = std::chrono::duration<double, std::nano>(t1 - t0).count() / N;
	}
	// Insertion sort for median/min/max.
	for (int i = 1; i < REPS; i++) {
		for (int j = i; j > 0 && results[j - 1] > results[j]; j--) {
			SWAP(results[j - 1], results[j]);
		}
	}
	printf("%s: median %6.1f ns/op, min %6.1f, max %6.1f\n", p_name, results[REPS / 2], results[0], results[REPS - 1]);
}

static void bench_object_alloc() {
	printf("--- C++ alloc bench, N=%d, reps=%d ---\n", N, REPS);
	run_bench("memnew(Object)+memdelete    ", []() {
		for (int i = 0; i < N; i++) {
			Object *o = memnew(Object);
			sink += (uintptr_t)o;
			memdelete(o);
		}
	});
	run_bench("memnew(Node)+memdelete      ", []() {
		for (int i = 0; i < N; i++) {
			Node *n = memnew(Node);
			sink += (uintptr_t)n;
			memdelete(n);
		}
	});
	run_bench("Ref<RefCounted> new+release ", []() {
		for (int i = 0; i < N; i++) {
			Ref<RefCounted> r;
			r.instantiate();
			sink += (uintptr_t)r.ptr();
		}
	});
	run_bench("Ref<Resource> new+release   ", []() {
		for (int i = 0; i < N; i++) {
			Ref<Resource> r;
			r.instantiate();
			sink += (uintptr_t)r.ptr();
		}
	});
	printf("sink: %" PRIuPTR "\n", sink);
}

REGISTER_TEST_COMMAND("bench-object-alloc", &bench_object_alloc)
```

## GDScript benchmark

Run with `godot --headless -s bench_alloc.gd`:

```gdscript
extends SceneTree

const N := 1_000_000
const REPS := 7

func bench_object() -> float:
	var t0 := Time.get_ticks_usec()
	for i in N:
		var o := Object.new()
		o.free()
	return (Time.get_ticks_usec() - t0) / float(N) * 1000.0 # ns/op

func bench_node() -> float:
	var t0 := Time.get_ticks_usec()
	for i in N:
		var n := Node.new()
		n.free()
	return (Time.get_ticks_usec() - t0) / float(N) * 1000.0

func bench_refcounted() -> float:
	var t0 := Time.get_ticks_usec()
	for i in N:
		var r := RefCounted.new()
	return (Time.get_ticks_usec() - t0) / float(N) * 1000.0

func bench_resource() -> float:
	var t0 := Time.get_ticks_usec()
	for i in N:
		var r := Resource.new()
	return (Time.get_ticks_usec() - t0) / float(N) * 1000.0

func run_bench(bench_name: String, f: Callable) -> void:
	f.call() # Warmup.
	var results: Array[float] = []
	for rep in REPS:
		results.append(f.call())
	results.sort()
	print("%s: median %.1f ns/op, min %.1f, max %.1f" % [bench_name, results[REPS / 2], results[0], results[REPS - 1]])

func _init():
	print("--- GDScript alloc bench, N=%d, reps=%d ---" % [N, REPS])
	run_bench("Object.new+free   ", bench_object)
	run_bench("Node.new+free     ", bench_node)
	run_bench("RefCounted.new    ", bench_refcounted)
	run_bench("Resource.new      ", bench_resource)
	quit()
```
</details>

Object and RefCounted allocation are faster, Node is maybe very slightly slower (because it uses `Mutex` instead of `BinaryMutex`).

